97: fn select_credential(
98:     headers: &HeaderMap,
99:     forward_cookies: bool,
100:     session_cookie: &str,
101: ) -> Result<KratosCredential, AuthError> {
102:     let authorization_values: Vec<_> = headers.get_all(AUTHORIZATION).iter().collect();
103:     let cookie_values: Vec<_> = headers.get_all(COOKIE).iter().collect();
104:     if authorization_values.len() > 1 || cookie_values.len() > 1 {
105:         return Err(AuthError::Unauthorized(
106:             "multiple Kratos credential headers are not allowed".to_string(),
107:         ));
108:     }
109: 
110:     let authorization = authorization_values.first().copied();
111:     let session_cookie_value = if forward_cookies {
112:         cookie_values
113:             .first()
114:             .copied()
115:             .map(|header| extract_cookie(header, session_cookie))
116:             .transpose()?
117:             .flatten()
118:     } else {
119:         None
120:     };
121:     if authorization.is_some() && session_cookie_value.is_some() {
122:         return Err(AuthError::Unauthorized(
123:             "competing Kratos credentials are not allowed".to_string(),
124:         ));
125:     }
126:     if let Some(value) = authorization {
127:         if value.to_str().ok().is_none_or(|raw| raw.trim().is_empty()) {
128:             return Err(AuthError::Unauthorized(
129:                 "Kratos authorization credential is blank".to_string(),
130:             ));
131:         }
132:         return Ok(KratosCredential {
133:             kind: KratosCredentialKind::Authorization,
134:             cache_value: value.as_bytes().to_vec(),
135:             header_value: value.clone(),
136:         });
137:     }
138:     if let Some((header, value)) = session_cookie_value {
139:         return Ok(KratosCredential {
140:             kind: KratosCredentialKind::Cookie,
141:             cache_value: value.into_bytes(),
142:             header_value: header,
143:         });
144:     }
145:     Err(AuthError::Unauthorized(
146:         "Kratos session credential is missing".to_string(),
147:     ))
